"""Cooperative crossed_waypoints policy for agent_0."""

import json
import math
from skills import comms, frames, nav, safety


def extract_waypoint(data):
    """Robustly extract target (x, y) and radius from various message shapes."""
    if data is None:
        return None, 0.2
    if isinstance(data, (list, tuple)) and len(data) == 2:
        if all(isinstance(v, (int, float)) for v in data):
            return [float(data[0]), float(data[1])], 0.2
    if isinstance(data, dict):
        for key in ("center", "target", "pos", "position", "xy", "point"):
            val = data.get(key)
            if (
                isinstance(val, (list, tuple))
                and len(val) == 2
                and all(isinstance(v, (int, float)) for v in val)
            ):
                radius = data.get("radius", 0.2)
                try:
                    radius = float(radius)
                except (ValueError, TypeError):
                    radius = 0.2
                return [float(val[0]), float(val[1])], radius
        for subkey in (
            "waypoint",
            "peer_waypoint",
            "payload",
            "data",
            "target_waypoint",
        ):
            if subkey in data:
                res, rad = extract_waypoint(data[subkey])
                if res is not None:
                    return res, rad
    return None, 0.2


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["target_xy"] = None
    ctx.state["target_radius"] = 0.2
    ctx.state["target_received_t"] = None
    ctx.state["at_target"] = False
    ctx.state["last_reached"] = 0
    ctx.state["nav"] = {}
    ctx.state["hazard_state"] = {}
    ctx.state["tick_count"] = 0
    ctx.log("crossed_waypoints policy started for agent_0")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation

    my_prog = observation.get("scenario", {}).get("my_progress", {})
    reached = my_prog.get("reached", 0)
    last_reached = ctx.state.get("last_reached", 0)
    if reached > last_reached:
        ctx.log(
            f"Target {last_reached} completed! New progress: {reached}/{my_prog.get('required', 8)}"
        )
        ctx.state["last_reached"] = reached
        ctx.state["target_xy"] = None
        ctx.state["at_target"] = False
        ctx.state["nav"] = {}


def on_inbox(ctx, message):
    payload = comms.payload_of(message)
    sender = comms.sender_of(message)

    if isinstance(payload, dict):
        msg_type = payload.get("type")
        if msg_type in ("no_waypoint", "no_target") or (
            payload.get("target") is None and payload.get("center") is None
        ):
            if ctx.state.get("target_xy") is not None:
                ctx.log(f"Received no_target from {sender}")
                ctx.state["target_xy"] = None
                ctx.state["at_target"] = False
                ctx.state["nav"] = {}
            return

    new_xy, new_radius = extract_waypoint(payload)
    if new_xy is not None:
        curr = ctx.state.get("target_xy")
        if curr is None or (
            abs(curr[0] - new_xy[0]) > 0.02 or abs(curr[1] - new_xy[1]) > 0.02
        ):
            ctx.log(
                f"Received new target from {sender}: {new_xy}, radius: {new_radius}"
            )
            ctx.state["target_xy"] = new_xy
            ctx.state["target_radius"] = new_radius
            ctx.state["at_target"] = False
            ctx.state["nav"] = {}
            obs = ctx.state.get("observation")
            if obs:
                ctx.state["target_received_t"] = obs.get("t_sim")


def on_tick(ctx):
    ctx.state["tick_count"] = ctx.state.get("tick_count", 0) + 1
    obs = ctx.state.get("observation")
    if not obs:
        ctx.publish_action({"vx": 0.0, "vy": 0.0, "omega": 0.0})
        ctx.status({"mode": "waiting_for_observation"})
        return

    # 1. Broadcast peer waypoint to agent_1 every tick
    peer_wp = obs.get("scenario", {}).get("peer_waypoint")
    if peer_wp:
        out_msg = {
            "type": "peer_waypoint",
            "agent_id": peer_wp.get("agent_id", "agent_1"),
            "center": peer_wp.get("center"),
            "target": peer_wp.get("center"),
            "radius": peer_wp.get("radius", 0.2),
            "expires_in_s": peer_wp.get("expires_in_s"),
            "my_progress": obs.get("scenario", {}).get("my_progress"),
        }
    else:
        out_msg = {
            "type": "no_waypoint",
            "agent_id": "agent_1",
            "center": None,
            "target": None,
            "my_progress": obs.get("scenario", {}).get("my_progress"),
        }
    ctx.send_message(out_msg)

    # 2. Check if all our targets are complete
    my_prog = obs.get("scenario", {}).get("my_progress", {})
    if my_prog.get("reached", 0) >= my_prog.get("required", 8):
        action = safety.safe(
            obs, {"vx": 0.0, "vy": 0.0, "omega": 0.0}, min_clearance=0.08
        )
        ctx.publish_action(action)
        ctx.status({"mode": "all_targets_complete", "progress": my_prog})
        return

    # 3. Handle our target navigation
    target_xy = ctx.state.get("target_xy")
    if target_xy is None:
        action = safety.safe(
            obs, {"vx": 0.0, "vy": 0.0, "omega": 0.0}, min_clearance=0.08
        )
        ctx.publish_action(action)
        ctx.status(
            {
                "mode": "waiting_for_target",
                "progress": my_prog,
                "peer_wp_expires": round(peer_wp.get("expires_in_s", 0.0), 1)
                if peer_wp
                else None,
            }
        )
        return

    rx, ry, _theta = frames.pose_of(obs)
    dist = math.hypot(rx - target_xy[0], ry - target_xy[1])
    target_radius = ctx.state.get("target_radius", 0.2)

    # Hysteresis for arrival within circle: target radius is 0.20m.
    # We aim to get within 0.06m. Once within 0.06m, hold still as long as dist < 0.14m.
    if ctx.state.get("at_target", False):
        if dist > 0.14:
            ctx.state["at_target"] = False
            ctx.state["nav"] = {}
    else:
        if dist <= 0.06:
            ctx.state["at_target"] = True

    if ctx.state.get("at_target", False):
        action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
        mode = "holding_in_target"
    else:
        mode = "navigating"
        nav_state = ctx.state.setdefault("nav", {})
        action = nav.goto_point(
            obs,
            target_xy,
            nav_state,
            max_speed=0.18,
            arrival_radius=0.05,
            avoid_moving=True,
        )
        if action is None:
            action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
            ctx.state["at_target"] = True

    # Check peer safety / hazard avoidance
    if (
        action.get("vx", 0.0) != 0.0
        or action.get("vy", 0.0) != 0.0
        or action.get("omega", 0.0) != 0.0
    ):
        hazard_state = ctx.state.setdefault("hazard_state", {})
        action, h_mode = nav.hazard_gate(obs, action, hazard_state, gap=0.22)
        if h_mode:
            mode = f"hazard_{h_mode}"

    action = safety.safe(obs, action, min_clearance=0.08)
    ctx.publish_action(action)

    ctx.status(
        {
            "mode": mode,
            "target": [round(target_xy[0], 3), round(target_xy[1], 3)],
            "dist": round(dist, 3),
            "progress": my_prog,
            "peer_wp_expires": round(peer_wp.get("expires_in_s", 0.0), 1)
            if peer_wp
            else None,
        }
    )

